class Ftp {

        var $server;
        var $user;
        var $pass;
        var $conn_id;
        var $handle;
    
	function __construct( $server,$user,$pass )
	{
            $this->server=$server;
            $this->user=$user;
            $this->pass=$pass;
        
            $aux=ftp_connect($this->server);
            if(!$aux){
                echo "NO CONECTA AL FTP"; exit;
            }else{
                $this->conn_id = $aux;    
            }
            $login_result = ftp_login($this->conn_id, $this->user, $this->pass);
          
            ftp_set_option($this->conn_id, FTP_USEPASVADDRESS, false); // set ftp option
            ftp_pasv($this->conn_id, true); //make connection to passive mode
        }

        function recorrer($directory){
            $contents = ftp_nlist($this->conn_id, $directory);
            //var_dump($contents);
            return $contents;
        }
        
        /*descarga un fichero remoto. Devuelve true o false depende de si ha podido descargarlo*/
        function descargar($remotefile,$localfile){
            if(ftp_get($this->conn_id, $localfile, $remotefile, FTP_BINARY)){
                return true;
            }else{
                return false;
            }
        }
        
        /*elimina un fichero remoto. Devuelve true o false depende de si ha podido eliminarlo*/
        function eliminar($file){
            if(ftp_delete($this->conn_id, $file)){
                return true;
            }else{
                return false;
            }
        }
        
        function cerrar(){
            ftp_close($this->conn_id);
            fclose($this->handle);
            return true;
        }
        
        function listar_directorio($directory){
            return ftp_nlist($this->conn_id, $directory);
        }
               
        function subir_img($origen,$destino){
            $stringftp='ftp://'.$this->user.':'.$this->pass.'@'.$this->server.$destino;
            if(copy($origen, $stringftp)) {
                echo "Img subida!!!\n";
            }else{
                echo "NO subida:".$stringftp."\n";
            }
        }
        
        function crear_directorio($directory){
            ftp_mkdir($this->conn_id, $directory);
        }
}